,\r\n      };\r\n    } catch (error) {\r\n      if (this.isSecretMissingError(error)) {\r\n        return undefined;\r\n      }\r\n\r\n      throw error;\r\n    }\r\n  }\r\n\r\n  private isSecretMissingError(error: unknown): boolean {\r\n    if (typeof error !== \"object\" || error === null) {\r\n      return false;\r\n    }\r\n\r\n    const candidate = error as {\r\n      statusCode?: number;\r\n      code?: string;\r\n      details?: { error?: { code?: string } };\r\n    };\r\n\r\n    return (\r\n      candidate.statusCode === 404 ||\r\n      candidate.code === \"SecretNotFound\" ||\r\n      candidate.details?.error?.code === \"SecretNotFound\"\r\n    );\r\n  }\r\n}\r\n\n```\n\n### src\\types.ts\n```\nexport interface SecretRequest {\r\n  name: string;\r\n  defaultValue: string;\r\n  version?: string;\r\n}\r\n\r\nexport interface SecretValueResult {\r\n  name: string;\r\n  value: string;\r\n  version?: string;\r\n  expiresOn?: Date;\r\n  source: \"keyvault\" | \"default\";\r\n}\r\n\r\nexport interface SecretExpiryInfo {\r\n  name: string;\r\n  version?: string;\r\n  expiresOn?: Date;\r\n  isExpiringSoon: boolean;\r\n  daysUntilExpiry?: number;\r\n}\r\n\r\nexport interface CachedSecretRecord extends SecretValueResult {\r\n  cacheKey: string;\r\n  cachedAt: Date;\r\n}\r\n\r\nexport interface CacheOptions {\r\n  expiryWarningWindowMs?: number;\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check to